def resource_path(name):
    """Путь к файлу-ресурсу рядом со скриптом — а если игра собрана в
    один .exe через PyInstaller (--onefile), то внутри временной папки
    распаковки (sys._MEIPASS)."""
    base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base, name)


