def T(lang, key, *args):
    s = TEXTS.get(lang, TEXTS["ru"]).get(key, key)
    if args:
        try:
            return s.format(*args)
        except Exception:
            return s
    return s


def clamp(v, lo, hi):
    return max(lo, min(hi, v))


# ───────────────────────────── СОХРАНЕНИЕ ─────────────────────────────
def load_save():
    default = {
        "highscore": 0,
        "lang": "ru",
        "graphics": "low",
        "coins": 0,
        "upgrades": {"damage": 0, "firerate": 0, "hp": 0, "speed": 0},
    }
    try:
        with open(SAVE_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            default.update(data)
    except Exception:
        pass
    if default.get("lang") not in LANGUAGES:
        default["lang"] = "ru"
    if default.get("graphics") not in QUALITY_LEVELS:
        default["graphics"] = "low"
    if not isinstance(default.get("upgrades"), dict):
        default["upgrades"] = {}
    for item in SHOP_ITEMS:
        lvl = default["upgrades"].get(item["id"], 0)
        if not isinstance(lvl, int) or lvl < 0:
            lvl = 0
        default["upgrades"][item["id"]] = min(lvl, item["max"])
    if not isinstance(default.get("coins"), int) or default["coins"] < 0:
        default["coins"] = 0
    if not isinstance(default.get("highscore"), int) or default["highscore"] < 0:
        default["highscore"] = 0
    return default


def write_save(data):
    try:
        os.makedirs(SAVE_DIR, exist_ok=True)
        with open(SAVE_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)
    except Exception:
        pass


