def make_glow_dot(radius, color, core=True):
    """Мягкая светящаяся точка — используется для звёзд, искр, ядра выстрела."""
    size = max(4, radius * 4)
    surf = pygame.Surface((size, size), pygame.SRCALPHA)
    cx = cy = size / 2
    steps = radius * 2
    for i in range(steps, 0, -1):
        t = i / steps
        alpha = int(180 * (1 - t) ** 2)
        r = i
        pygame.draw.circle(surf, (*color, alpha), (int(cx), int(cy)), r)
    if core:
        pygame.draw.circle(surf, (255, 255, 255, 235), (int(cx), int(cy)), max(1, radius // 3))
    return surf


def make_star_sprites():
    return [
        make_glow_dot(1, WHITE, core=False),
        make_glow_dot(2, NEON_CYAN_SOFT, core=True),
        make_glow_dot(3, WHITE, core=True),
    ]


def make_nebula_sprite(w, h, color, seed):
    rnd = random.Random(seed)
    surf = pygame.Surface((w, h), pygame.SRCALPHA)
    blobs = 5
    for _ in range(blobs):
        bx = rnd.randint(0, w)
        by = rnd.randint(0, h)
        br = rnd.randint(int(w * 0.18), int(w * 0.34))
        layers = 10
        for i in range(layers, 0, -1):
            t = i / layers
            alpha = int(26 * (1 - t) ** 2)
            pygame.draw.circle(surf, (*color, alpha), (bx, by), int(br * t + br * 0.15))
    return surf


def make_bolt_frames(core_color, glow_color, n=6, seed=0):
    """Анимация выстрела: от маленькой светящейся точки до вытянутого луча
    с рассеянными искрами — повторяет стиль референса пользователя."""
    frames = []
    rnd = random.Random(seed)
    max_len = 58
    max_h = 22
    for i in range(n):
        t = i / (n - 1)
        length = int(10 + max_len * t)
        thick = int(9 + 4 * min(1.0, t * 1.6))
        w = length + 24
        h = max_h
        surf = pygame.Surface((w, h), pygame.SRCALPHA)
        cx, cy = w // 2, h // 2
        # внешнее свечение (вытянутый эллипс, несколько слоёв)
        glow_layers = 6
        for gl in range(glow_layers, 0, -1):
            gt = gl / glow_layers
            alpha = int(70 * (1 - gt) ** 1.6)
            ew = int(length * gt + 6)
            eh = int(thick * gt * 0.9 + 3)
            rect = pygame.Rect(0, 0, ew, eh)
            rect.center = (cx, cy)
            pygame.draw.ellipse(surf, (*glow_color, alpha), rect)
        # яркое ядро, смещено к переднему краю
        core_rect = pygame.Rect(0, 0, int(length * 0.6 + 6), int(thick * 0.55 + 2))
        core_rect.center = (cx + int(length * 0.18), cy)
        pygame.draw.ellipse(surf, (255, 255, 255, 235), core_rect)
        head_r = max(3, int(thick * 0.42))
        pygame.draw.circle(surf, (255, 255, 255, 255), (cx + length // 2, cy), head_r)
        # искры вдоль хвоста
        sparks = int(2 + i * 1.6)
        for _ in range(sparks):
            sx = cx - rnd.randint(0, length // 2 + 6)
            sy = cy + rnd.randint(-thick // 2, thick // 2)
            sr = rnd.randint(1, 2)
            salpha = rnd.randint(90, 200)
            pygame.draw.circle(surf, (*glow_color, salpha), (sx, sy), sr)
        frames.append(surf)
    return frames


def make_explosion_frames(color, n=5, size=90, seed=1):
    rnd = random.Random(seed)
    frames = []
    ray_count = 10
    ray_angles = [rnd.uniform(0, math.tau) for _ in range(ray_count)]
    ray_lengths = [rnd.uniform(0.6, 1.0) for _ in range(ray_count)]
    spark_pts = [(rnd.uniform(0, math.tau), rnd.uniform(0.3, 1.0)) for _ in range(22)]
    for i in range(n):
        t = i / (n - 1)
        surf = pygame.Surface((size, size), pygame.SRCALPHA)
        cx = cy = size // 2
        radius = size * 0.5 * (0.25 + t * 0.85)
        fade = 1.0 - (t ** 1.6) if i > 0 else 1.0
        alpha_main = int(230 * fade)
        # мягкое общее свечение
        for gl in range(4, 0, -1):
            gt = gl / 4
            a = int(70 * fade * (1 - gt) ** 1.3)
            pygame.draw.circle(surf, (*color, a), (cx, cy), int(radius * gt + radius * 0.2))
        # лучи
        for ang, ln in zip(ray_angles, ray_lengths):
            L = radius * ln * (0.5 + t)
            ex = cx + math.cos(ang) * L
            ey = cy + math.sin(ang) * L
            pygame.draw.line(surf, (*color, int(alpha_main * 0.7)), (cx, cy), (int(ex), int(ey)), max(1, int(3 * fade)))
        # яркое ядро
        core_r = max(1, int(radius * (0.55 - 0.35 * t)))
        pygame.draw.circle(surf, (255, 255, 255, alpha_main), (cx, cy), core_r)
        # искры
        for ang, frac in spark_pts:
            L = radius * frac * (0.6 + t * 0.8)
            px = cx + math.cos(ang) * L
            py = cy + math.sin(ang) * L
            pygame.draw.circle(surf, (*color, int(200 * fade)), (int(px), int(py)), 2)
        frames.append(surf)
    return frames


def load_texture(b64_data, target_h):
    """Декодирует встроенный PNG (base64) в поверхность заданной высоты."""
    try:
        raw = base64.b64decode(b64_data)
        surf = pygame.image.load(io.BytesIO(raw), "ship.png").convert_alpha()
        w, h = surf.get_size()
        target_w = max(1, int(w * target_h / h))
        return pygame.transform.smoothscale(surf, (target_w, target_h))
    except Exception:
        return None


def make_ship_sprite(main_color, accent_color, scale=1.0, flip_y=False):
    w, h = int(48 * scale), int(56 * scale)
    surf = pygame.Surface((w, h), pygame.SRCALPHA)
    cx = w // 2
    body = [
        (cx, 2), (w - 8, h - 18), (w - 16, h - 8), (cx + 6, h - 16),
        (cx - 6, h - 16), (16, h - 8), (8, h - 18),
    ]
    pygame.draw.polygon(surf, main_color, body)
    pygame.draw.polygon(surf, (255, 255, 255, 60), body, width=2)
    # кокпит
    pygame.draw.ellipse(surf, (30, 40, 60), (cx - 6, 12, 12, 16))
    pygame.draw.ellipse(surf, (*accent_color, 220), (cx - 4, 14, 8, 10))
    # крылья-акценты
    pygame.draw.polygon(surf, accent_color, [(6, h - 20), (18, h - 26), (18, h - 10), (6, h - 8)])
    pygame.draw.polygon(surf, accent_color, [(w - 6, h - 20), (w - 18, h - 26), (w - 18, h - 10), (w - 6, h - 8)])
    if flip_y:
        surf = pygame.transform.flip(surf, False, True)
    return surf


def make_enemy_sprite(kind):
    if kind == "fast":
        color, accent = (255, 120, 90), (255, 200, 120)
    elif kind == "shooter":
        color, accent = (200, 90, 255), (255, 150, 255)
    else:
        color, accent = NEON_RED, (255, 170, 150)
    return make_ship_sprite(color, accent, scale=0.95, flip_y=True)


# ═══════════════════════ ПРОЦЕДУРНЫЙ ЗВУК ═══════════════════════

def _tone(freq, dur, vol=0.4, kind="sine", sr=44100, sweep=0.0):
    n = int(sr * dur)
    t = np.linspace(0, dur, n, endpoint=False)
    f = freq + sweep * t
    if kind == "sine":
        wave = np.sin(2 * np.pi * f * t)
    elif kind == "square":
        wave = np.sign(np.sin(2 * np.pi * f * t))
    elif kind == "noise":
        wave = np.random.uniform(-1, 1, n)
    else:
        wave = np.sin(2 * np.pi * f * t)
    envelope = np.linspace(1, 0, n) ** 1.5
    wave = wave * envelope * vol
    stereo = np.column_stack((wave, wave))
    audio = (stereo * 32767).astype(np.int16)
    return audio


def make_sounds():
    sounds = {}
    if not SOUND_ENABLED:
        return sounds
    try:
        sounds["shoot"] = pygame.sndarray.make_sound(_tone(880, 0.09, 0.25, "square", sweep=-1400))
        sounds["shoot2"] = pygame.sndarray.make_sound(_tone(660, 0.09, 0.22, "square", sweep=-1000))
        sounds["explosion"] = pygame.sndarray.make_sound(_tone(140, 0.35, 0.35, "noise", sweep=-60))
        sounds["hit"] = pygame.sndarray.make_sound(_tone(220, 0.12, 0.3, "square", sweep=-300))
        sounds["coin"] = pygame.sndarray.make_sound(_tone(1200, 0.12, 0.25, "sine", sweep=600))
        sounds["select"] = pygame.sndarray.make_sound(_tone(500, 0.06, 0.2, "sine", sweep=300))
        sounds["confirm"] = pygame.sndarray.make_sound(_tone(700, 0.1, 0.25, "sine", sweep=500))
        sounds["buy"] = pygame.sndarray.make_sound(_tone(900, 0.15, 0.28, "sine", sweep=400))
        sounds["gameover"] = pygame.sndarray.make_sound(_tone(300, 0.6, 0.3, "square", sweep=-220))
    except Exception:
        return {}
    return sounds


# ═══════════════════════ ИГРОВЫЕ СУЩНОСТИ ═══════════════════════

class Star:
    __slots__ = ("x", "y", "speed", "sprite_idx", "twinkle", "phase")

    def __init__(self, rnd):
        self.x = rnd.uniform(0, LOGICAL_W)
        self.y = rnd.uniform(0, LOGICAL_H)
        layer = rnd.random()
        if layer < 0.6:
            self.speed = rnd.uniform(18, 45)
            self.sprite_idx = 0
        elif layer < 0.88:
            self.speed = rnd.uniform(45, 90)
            self.sprite_idx = 1
        else:
            self.speed = rnd.uniform(90, 150)
            self.sprite_idx = 2
        self.twinkle = rnd.random() < 0.3
        self.phase = rnd.uniform(0, math.tau)


class Bolt:
    __slots__ = ("x", "y", "vx", "vy", "team", "dmg", "anim_t", "alive", "radius")

    def __init__(self, x, y, vx, vy, team, dmg):
        self.x, self.y, self.vx, self.vy = x, y, vx, vy
        self.team = team
        self.dmg = dmg
        self.anim_t = 0.0
        self.alive = True
        self.radius = 9


class Particle:
    __slots__ = ("x", "y", "vx", "vy", "life", "maxlife", "color", "size")

    def __init__(self, x, y, vx, vy, life, color, size):
        self.x, self.y, self.vx, self.vy = x, y, vx, vy
        self.life = life
        self.maxlife = life
        self.color = color
        self.size = size


class Blast:
    __slots__ = ("x", "y", "t", "dur", "frames", "scale")

    def __init__(self, x, y, frames, dur=0.32, scale=1.0):
        self.x, self.y = x, y
        self.t = 0.0
        self.dur = dur
        self.frames = frames
        self.scale = scale


class Enemy:
    __slots__ = ("x", "y", "vx", "vy", "hp", "maxhp", "kind", "sprite", "shoot_cd",
                 "shoot_timer", "score", "coins", "wobble", "radius", "flash")

    def __init__(self, x, y, kind, wave, sprite):
        self.x, self.y = x, y
        self.kind = kind
        self.sprite = sprite
        self.wobble = random.uniform(0, math.tau)
        self.radius = 18
        self.flash = 0.0
        if kind == "fast":
            self.hp = self.maxhp = 2 + wave // 3
            self.vy = random.uniform(120, 160)
            self.vx = 0
            self.shoot_cd = None
            self.score, self.coins = 15, 4
        elif kind == "shooter":
            self.hp = self.maxhp = 3 + wave // 2
            self.vy = random.uniform(45, 65)
            self.vx = 0
            self.shoot_cd = max(1.1, 2.4 - wave * 0.05)
            self.shoot_timer = random.uniform(0.5, self.shoot_cd)
            self.score, self.coins = 25, 6
        elif kind == "boss":
            self.hp = self.maxhp = 60 + wave * 14
            self.vy = 70
            self.vx = 90
            self.radius = 62
            self.shoot_cd = max(0.55, 1.3 - wave * 0.015)
            self.shoot_timer = 1.2
            self.score, self.coins = 400 + wave * 20, 60 + wave * 4
        else:
            self.hp = self.maxhp = 2 + wave // 2
            self.vy = random.uniform(60, 90)
            self.vx = 0
            self.shoot_cd = None
            self.score, self.coins = 10, 3


class Player:
    def __init__(self, x, y, color, accent, keymap, upgrades, texture=None):
        self.x, self.y = x, y
        self.color = color
        self.sprite = texture if texture is not None else make_ship_sprite(color, accent, scale=1.0)
        self.keymap = keymap
        dmg_lvl = upgrades.get("damage", 0)
        fr_lvl = upgrades.get("firerate", 0)
        hp_lvl = upgrades.get("hp", 0)
        sp_lvl = upgrades.get("speed", 0)
        self.damage = 1.0 + 0.4 * dmg_lvl
        self.fire_cd = max(0.10, 0.28 - fr_lvl * 0.024)
        self.maxhp = 3 + hp_lvl
        self.hp = self.maxhp
        self.speed = 250 + sp_lvl * 20
        self.fire_timer = 0.0
        self.alive = True
        self.invuln = 0.0
        self.radius = 16
        self.flash = 0.0

    def input_state(self, keys):
        km = self.keymap
        dx = (1 if keys[km["right"]] else 0) - (1 if keys[km["left"]] else 0)
        dy = (1 if keys[km["down"]] else 0) - (1 if keys[km["up"]] else 0)
        shoot = keys[km["shoot"]]
        return dx, dy, shoot


# ═══════════════════════ ОСНОВНОЙ КЛАСС ИГРЫ ═══════════════════════

class App(ExtensionsMixin):
    def __init__(self):
        self.data = load_save()
        self.lang = self.data["lang"]
        self.quality = self.data["graphics"]

        self.window = pygame.display.set_mode((LOGICAL_W, LOGICAL_H), pygame.RESIZABLE)
        pygame.display.set_caption("Neon Defender")
        try:
            icon_path = os.path.join(getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__))), "icon.ico")
            if os.path.isfile(icon_path):
                pygame.display.set_icon(pygame.image.load(icon_path))
        except Exception:
            pass

        self.canvas = pygame.Surface((LOGICAL_W, LOGICAL_H))
        self.fullscreen = False
        self.clock = pygame.time.Clock()

        font_file = CUSTOM_FONT_PATH if os.path.isfile(CUSTOM_FONT_PATH) else None
        try:
            self.font_title = pygame.font.Font(font_file, 76)
            self.font_big = pygame.font.Font(font_file, 46)
            self.font_med = pygame.font.Font(font_file, 30)
            self.font_small = pygame.font.Font(font_file, 22)
            self.font_tiny = pygame.font.Font(font_file, 16)
        except Exception:
            # если со шрифтом что-то не так — не роняем игру, просто
            # откатываемся на системный шрифт pygame по умолчанию
            self.font_title = pygame.font.Font(None, 88)
            self.font_big = pygame.font.Font(None, 52)
            self.font_med = pygame.font.Font(None, 34)
            self.font_small = pygame.font.Font(None, 24)
            self.font_tiny = pygame.font.Font(None, 18)

        self.star_sprites = make_star_sprites()
        self.rebuild_quality_assets()

        self.bolt_frames_player = make_bolt_frames(WHITE, NEON_CYAN, seed=1)
        self.bolt_frames_enemy = make_bolt_frames((255, 230, 220), NEON_RED, seed=2)
        self.blast_frames_small = make_explosion_frames(NEON_CYAN, size=70, seed=3)
        self.blast_frames_big = make_explosion_frames(NEON_YELLOW, size=130, seed=4)

        self.sounds = make_sounds()

        # текстуры кораблей: белая — игрок, тёмная — враги, отдельная — босс
        self.player_texture = load_texture(PLAYER_SHIP_PNG_B64, 58)
        enemy_tex = load_texture(ENEMY_SHIP_PNG_B64, 54)
        if enemy_tex is not None:
            enemy_tex = pygame.transform.flip(enemy_tex, False, True)
        self.enemy_texture = enemy_tex
        self.boss_texture = load_texture(BOSS_SHIP_PNG_B64, 140)

        if self.enemy_texture is not None:
            self.enemy_sprites = {k: self.enemy_texture for k in ("basic", "fast", "shooter")}
        else:
            self.enemy_sprites = {k: make_enemy_sprite(k) for k in ("basic", "fast", "shooter")}
        if self.boss_texture is None:
            self.boss_texture = make_ship_sprite(NEON_RED, (255, 170, 150), scale=2.4, flip_y=True)
        self.scanline_overlay = self.make_scanline_overlay()

        self.show_fps = False
        self.scanlines = QUALITY_SETTINGS[self.quality]["scanlines"]
        self.running = True

        self.state = "menu"
        self.menu_index = 0
        self.menu_keys = ["play1", "play2", "multiplayer", "shop", "stats", "info", "netset", "settings", "quit"]
        self.settings_index = 0
        self.shop_index = 0
        self.paused = False

        self.rnd = random.Random()
        self.reset_session_vars()
        self.init_network_state()
        try:
            self.init_extensions(SAVE_DIR, GAME_VERSION)
            self.start_match_tracking()
        except Exception:
            import traceback
            traceback.print_exc()  # расширения не должны мешать запуску игры

    # ───────── сетевое состояние (LAN co-op) ─────────
    def init_network_state(self):
        self.net_role = None          # None | "host" | "client"
        self.net_server = None        # network.LANServer
        self.net_client = None        # network.LANClient
        self.net_advertiser = None    # network.LobbyAdvertiser (HOST рассылает объявление)
        self.net_browser = None       # network.LobbyBrowser (CLIENT слушает объявления)
        self.mp_browse_index = 0
        self.mp_menu_index = 0
        self.mp_lobby_players = {}    # id -> name (клиенты хоста)
        self.mp_error = None
        self.mp_ip_text = ""
        self.mp_port_text = str(net.DEFAULT_PORT)
        self.mp_field = "ip"
        self.mp_connect_thread = None
        self._mp_connect_queue = queue.Queue()
        self.mp_connecting = False
        self.mp_wait_start = False
        self.net_send_accum = 0.0
        self.net_snapshot = None      # последнее состояние, полученное клиентом
        self.net_last_input_by_id = {}  # host: id -> {"dx","dy","shoot"}
        self.net_ping_ms = 0

    def net_cleanup(self):
        if self.net_server:
            try:
                self.net_server.stop()
            except Exception:
                pass
        if self.net_client:
            try:
                self.net_client.disconnect()
            except Exception:
                pass
        if getattr(self, "net_advertiser", None):
            try:
                self.net_advertiser.stop()
            except Exception:
                pass
        if getattr(self, "net_browser", None):
            try:
                self.net_browser.stop()
            except Exception:
                pass
        self.net_role = None
        self.net_server = None
        self.net_client = None
        self.net_advertiser = None
        self.net_browser = None
        self.mp_browse_index = 0
        self.mp_lobby_players = {}
        self.net_snapshot = None
        self.mp_connecting = False
        self.mp_wait_start = False

    # ───────── вспомогательное ─────────
    def t(self, key, *args):
        return T(self.lang, key, *args)

    def play_sound(self, name):
        s = self.sounds.get(name)
        if s:
            try:
                s.play()
            except Exception:
                pass

    def rebuild_quality_assets(self):
        qs = QUALITY_SETTINGS[self.quality]
        self.stars = [Star(random.Random(i * 7919 + 13)) for i in range(qs["stars"])]
        nebula_colors = [(70, 40, 140), (30, 90, 160), (140, 40, 110)]
        self.nebulae = []
        for i in range(qs["nebulae"]):
            spr = make_nebula_sprite(LOGICAL_W, LOGICAL_H, nebula_colors[i % len(nebula_colors)], seed=i * 31 + 5)
            self.nebulae.append({"surf": spr, "y": i * 220.0, "speed": 6 + i * 3})
        self.bg_grad = self.make_bg_gradient()

    def make_bg_gradient(self):
        surf = pygame.Surface((1, LOGICAL_H))
        for y in range(LOGICAL_H):
            t = y / LOGICAL_H
            r = int(BG_TOP[0] + (BG_BOTTOM[0] - BG_TOP[0]) * t)
            g = int(BG_TOP[1] + (BG_BOTTOM[1] - BG_TOP[1]) * t)
            b = int(BG_TOP[2] + (BG_BOTTOM[2] - BG_TOP[2]) * t)
            surf.set_at((0, y), (r, g, b))
        return pygame.transform.scale(surf, (LOGICAL_W, LOGICAL_H))

    def save(self):
        self.data["lang"] = self.lang
        self.data["graphics"] = self.quality
        write_save(self.data)

    def toggle_fullscreen(self):
        self.fullscreen = not self.fullscreen
        if self.fullscreen:
            info = pygame.display.Info()
            self.window = pygame.display.set_mode((info.current_w, info.current_h), pygame.FULLSCREEN)
        else:
            self.window = pygame.display.set_mode((LOGICAL_W, LOGICAL_H), pygame.RESIZABLE)

    # ───────── сессия игры ─────────
    def reset_session_vars(self):
        self.players = []
        self.enemies = []
        self.bolts = []
        self.particles = []
        self.blasts = []
        self.score = 0
        self.combo = 1
        self.combo_timer = 0.0
        self.wave = 1
        self.wave_timer = 2.0
        self.spawn_timer = 0.0
        self.spawned_in_wave = 0
        self.enemies_per_wave = 6
        self.earned_coins = 0
        self.two_player = False
        self.shake = 0.0

    def start_run(self, two_player):
        self.reset_session_vars()
        self.two_player = two_player
        upgrades = self.data["upgrades"]
        km1 = {"left": pygame.K_a, "right": pygame.K_d, "up": pygame.K_w, "down": pygame.K_s, "shoot": pygame.K_SPACE}
        p1 = Player(LOGICAL_W * (0.5 if not two_player else 0.35), LOGICAL_H - 90, PLAYER1_COLOR, NEON_CYAN, km1, upgrades, texture=self.player_texture)
        self.players.append(p1)
        if two_player:
            km2 = {"left": pygame.K_LEFT, "right": pygame.K_RIGHT, "up": pygame.K_UP, "down": pygame.K_DOWN, "shoot": pygame.K_RETURN}
            p2 = Player(LOGICAL_W * 0.65, LOGICAL_H - 90, PLAYER2_COLOR, NEON_PINK, km2, upgrades, texture=self.player_texture)
            self.players.append(p2)
        self.state = "playing"
        self.paused = False
        try:
            self.start_match_tracking()
        except Exception:
            pass

    def end_run(self):
        self.record_profile_match()
        if self.score > self.data["highscore"]:
            self.data["highscore"] = self.score
        self.data["coins"] += self.earned_coins
        write_save(self.data)
        self.state = "gameover"

    def quit_to_menu(self):
        """Выход в меню с паузы — прогресс (монеты, рекорд) не теряется."""
        if self.score > self.data["highscore"]:
            self.data["highscore"] = self.score
        self.data["coins"] += self.earned_coins
        self.earned_coins = 0
        write_save(self.data)
        self.record_profile_match()
        self.state = "menu"
        self.menu_index = 0
        self.paused = False

    # ───────── обновление игрового мира ─────────
    def update_playing(self, dt, keys):
        qs = QUALITY_SETTINGS[self.quality]
        any_alive = any(p.alive for p in self.players)
        if not any_alive:
            self.end_run()
            return

        for p in self.players:
            if not p.alive:
                continue
            dx, dy, shoot = p.input_state(keys)
            norm = math.hypot(dx, dy) or 1
            if dx or dy:
                p.x += (dx / norm) * p.speed * dt
                p.y += (dy / norm) * p.speed * dt
            p.x = clamp(p.x, 24, LOGICAL_W - 24)
            p.y = clamp(p.y, 60, LOGICAL_H - 24)
            p.fire_timer -= dt
            if p.invuln > 0:
                p.invuln -= dt
            p.flash = max(0.0, p.flash - dt * 4)
            if shoot and p.fire_timer <= 0:
                p.fire_timer = p.fire_cd
                self.bolts.append(Bolt(p.x, p.y - 26, 0, -620, "player", p.damage))
                self.play_sound("shoot")

        # спавн волны
        self.wave_timer -= dt
        if self.spawned_in_wave < self.enemies_per_wave:
            self.spawn_timer -= dt
            if self.spawn_timer <= 0:
                self.spawn_timer = max(0.35, 1.0 - self.wave * 0.03)
                self.spawn_enemy()
        elif not self.enemies and self.wave_timer <= 0:
            self.wave += 1
            if self.wave % 10 == 0:
                self.enemies_per_wave = 0
                self.spawned_in_wave = 0
                self.wave_timer = 1.2
                self.spawn_boss()
            else:
                self.enemies_per_wave = 5 + self.wave * 2
                self.spawned_in_wave = 0
                self.wave_timer = 2.2

        # враги
        for e in list(self.enemies):
            e.wobble += dt * 2.2
            if e.kind == "boss":
                self.update_boss(e, dt)
            else:
                e.x += math.sin(e.wobble) * 34 * dt
                e.y += e.vy * dt
            e.flash = max(0.0, e.flash - dt * 5)
            if e.kind == "shooter":
                e.shoot_timer -= dt
                if e.shoot_timer <= 0 and e.y > 20:
                    e.shoot_timer = e.shoot_cd
                    self.bolts.append(Bolt(e.x, e.y + 24, 0, 300, "enemy", 1))
            if e.kind != "boss" and e.y > LOGICAL_H + 30:
                self.enemies.remove(e)
                continue
            # столкновение с игроками
            for p in self.players:
                if not p.alive or p.invuln > 0:
                    continue
                if math.hypot(p.x - e.x, p.y - e.y) < p.radius + e.radius:
                    self.damage_player(p, 1)
                    if e.kind != "boss":
                        e.hp = 0

        for e in list(self.enemies):
            if e.hp <= 0:
                self.kill_enemy(e)

        # выстрелы
        for b in list(self.bolts):
            b.x += b.vx * dt
            b.y += b.vy * dt
            b.anim_t += dt
            if b.y < -40 or b.y > LOGICAL_H + 40:
                self.bolts.remove(b)
                continue
            if b.team == "player":
                hit = None
                for e in self.enemies:
                    if math.hypot(b.x - e.x, b.y - e.y) < e.radius + b.radius:
                        hit = e
                        break
                if hit:
                    hit.hp -= b.dmg
                    hit.flash = 1.0
                    self.spawn_hit_particles(b.x, b.y, NEON_CYAN, qs["particles"] // 2)
                    if b in self.bolts:
                        self.bolts.remove(b)
                    if hit.hp <= 0:
                        self.kill_enemy(hit)
                    else:
                        self.play_sound("hit")
            else:
                for p in self.players:
                    if not p.alive or p.invuln > 0:
                        continue
                    if math.hypot(b.x - p.x, b.y - p.y) < p.radius + b.radius:
                        self.damage_player(p, 1)
                        if b in self.bolts:
                            self.bolts.remove(b)
                        break

        # частицы
        for pa in list(self.particles):
            pa.life -= dt
            if pa.life <= 0:
                self.particles.remove(pa)
                continue
            pa.x += pa.vx * dt
            pa.y += pa.vy * dt
            pa.vx *= 0.98
            pa.vy *= 0.98

        for bl in list(self.blasts):
            bl.t += dt
            if bl.t >= bl.dur:
                self.blasts.remove(bl)

        if self.combo_timer > 0:
            self.combo_timer -= dt
            if self.combo_timer <= 0:
                self.combo = 1

        self.shake = max(0.0, self.shake - dt * 6)

        # звёзды всегда двигаются (и в игре, и в меню)
        self.update_stars(dt)

    def damage_player(self, p, amount):
        p.hp -= amount
        p.invuln = 1.4
        p.flash = 1.0
        self.shake = min(1.0, self.shake + 0.35)
        self.play_sound("hit")
        cx, cy = p.x, p.y
        self.blasts.append(Blast(cx, cy, self.blast_frames_small, dur=0.28))
        if p.hp <= 0:
            p.alive = False
            self.run_deaths = getattr(self, "run_deaths", 0) + 1
            self.blasts.append(Blast(cx, cy, self.blast_frames_big, dur=0.5, scale=1.1))
            self.play_sound("explosion")

    def kill_enemy(self, e):
        if e not in self.enemies:
            return None
        self.enemies.remove(e)
        self.run_kills = getattr(self, "run_kills", 0) + 1
        self.combo = min(9, self.combo + 1)
        self.combo_timer = 1.6
        gained = e.score * self.combo
        self.score += gained
        self.earned_coins += e.coins
        self.blasts.append(Blast(e.x, e.y, self.blast_frames_big, dur=0.4))
        self.spawn_hit_particles(e.x, e.y, NEON_YELLOW, QUALITY_SETTINGS[self.quality]["particles"])
        self.play_sound("explosion")
        return True

    def spawn_hit_particles(self, x, y, color, count):
        for _ in range(count):
            ang = random.uniform(0, math.tau)
            spd = random.uniform(40, 220)
            self.particles.append(Particle(
                x, y, math.cos(ang) * spd, math.sin(ang) * spd,
                random.uniform(0.25, 0.6), color, random.uniform(1.5, 3.5)
            ))

    def spawn_enemy(self):
        qs_wave = self.wave
        roll = random.random()
        if qs_wave >= 4 and roll < 0.22:
            kind = "shooter"
        elif qs_wave >= 2 and roll < 0.45:
            kind = "fast"
        else:
            kind = "basic"
        x = random.uniform(40, LOGICAL_W - 40)
        sprite = self.enemy_sprites[kind]
        self.enemies.append(Enemy(x, -30, kind, self.wave, sprite))
        self.spawned_in_wave += 1

    def spawn_boss(self):
        boss = Enemy(LOGICAL_W / 2, -140, "boss", self.wave, self.boss_texture)
        self.enemies.append(boss)
        self.play_sound("gameover")

    def update_boss(self, e, dt):
        """Босс спускается до фиксированной высоты, затем ходит из стороны
        в сторону и стреляет веером выстрелов."""
        if e.y < 130:
            e.y += e.vy * dt
            return
        e.y = 130
        e.x += e.vx * dt
        if e.x < 90:
            e.x, e.vx = 90, abs(e.vx)
        elif e.x > LOGICAL_W - 90:
            e.x, e.vx = LOGICAL_W - 90, -abs(e.vx)
        e.shoot_timer -= dt
        if e.shoot_timer <= 0:
            e.shoot_timer = e.shoot_cd
            for ang in (-0.34, 0.0, 0.34):
                vx_b = math.sin(ang) * 300
                vy_b = math.cos(ang) * 300
                self.bolts.append(Bolt(e.x, e.y + 50, vx_b, vy_b, "enemy", 1))
            self.play_sound("shoot2")

    def update_stars(self, dt):
        for s in self.stars:
            s.y += s.speed * dt
            if s.y > LOGICAL_H + 4:
                s.y = -4
                s.x = random.uniform(0, LOGICAL_W)
        for neb in self.nebulae:
            neb["y"] += neb["speed"] * dt
            if neb["y"] > LOGICAL_H:
                neb["y"] = -LOGICAL_H

    # ───────── отрисовка ─────────
    def draw_background(self, surf):
        surf.blit(self.bg_grad, (0, 0))
        for neb in self.nebulae:
            surf.blit(neb["surf"], (0, int(neb["y"])))
            surf.blit(neb["surf"], (0, int(neb["y"] - LOGICAL_H)))
        ticks = pygame.time.get_ticks()
        for s in self.stars:
            spr = self.star_sprites[s.sprite_idx]
            pos = (s.x - spr.get_width() / 2, s.y - spr.get_height() / 2)
            if s.twinkle:
                alpha = int(150 + 105 * math.sin(ticks * 0.004 + s.phase))
                spr2 = spr.copy()
                spr2.set_alpha(clamp(alpha, 60, 255))
                surf.blit(spr2, pos, special_flags=pygame.BLEND_RGBA_ADD)
            else:
                surf.blit(spr, pos, special_flags=pygame.BLEND_RGBA_ADD)

    def draw_bolt(self, surf, b):
        frames = self.bolt_frames_player if b.team == "player" else self.bolt_frames_enemy
        idx = int((b.anim_t * 22)) % len(frames)
        spr = frames[idx]
        angle = 90 if b.vy < 0 else -90
        rot = pygame.transform.rotate(spr, angle)
        rect = rot.get_rect(center=(int(b.x), int(b.y)))
        surf.blit(rot, rect, special_flags=pygame.BLEND_RGBA_ADD)

    def draw_ship(self, surf, p):
        if not p.alive:
            return
        if p.invuln > 0 and int(p.invuln * 14) % 2 == 0:
            return
        rect = p.sprite.get_rect(center=(int(p.x), int(p.y)))
        surf.blit(p.sprite, rect)
        if p.flash > 0:
            flash_spr = p.sprite.copy()
            flash_spr.fill((255, 255, 255, int(180 * p.flash)), special_flags=pygame.BLEND_RGBA_MULT)
            surf.blit(flash_spr, rect, special_flags=pygame.BLEND_RGBA_ADD)

    def draw_enemy(self, surf, e):
        rect = e.sprite.get_rect(center=(int(e.x), int(e.y)))
        surf.blit(e.sprite, rect)
        if e.flash > 0:
            flash_spr = e.sprite.copy()
            flash_spr.set_alpha(int(200 * e.flash))
            surf.blit(flash_spr, rect, special_flags=pygame.BLEND_RGBA_ADD)
        if e.kind == "boss":
            bar_w, bar_h = 240, 10
            bx, by = LOGICAL_W / 2 - bar_w / 2, 18
            pygame.draw.rect(surf, (40, 10, 10, 200), (bx, by, bar_w, bar_h), border_radius=4)
            frac = max(0.0, e.hp / e.maxhp)
            pygame.draw.rect(surf, NEON_RED, (bx, by, bar_w * frac, bar_h), border_radius=4)
            pygame.draw.rect(surf, (255, 255, 255, 120), (bx, by, bar_w, bar_h), width=1, border_radius=4)

    def draw_hud(self, surf):
        pad = 16
        score_s = self.font_med.render(self.t("score", self.score), True, WHITE)
        surf.blit(score_s, (pad, pad))
        best = max(self.data["highscore"], self.score)
        best_s = self.font_small.render(self.t("best", best), True, GRAY)
        surf.blit(best_s, (pad, pad + 36))
        wave_s = self.font_med.render(self.t("wave", self.wave), True, NEON_CYAN_SOFT)
        surf.blit(wave_s, (LOGICAL_W - wave_s.get_width() - pad, pad))
        if self.combo > 1:
            combo_s = self.font_small.render(self.t("combo", self.combo), True, NEON_YELLOW)
            surf.blit(combo_s, (LOGICAL_W - combo_s.get_width() - pad, pad + 36))
        # полоски HP
        for i, p in enumerate(self.players):
            bx = pad + i * 180
            by = LOGICAL_H - 28
            bw, bh = 150, 14
            pygame.draw.rect(surf, DARK_GRAY, (bx, by, bw, bh), border_radius=4)
            frac = clamp(p.hp / p.maxhp, 0, 1) if p.alive else 0
            col = p.color if p.alive else (90, 40, 40)
            pygame.draw.rect(surf, col, (bx, by, int(bw * frac), bh), border_radius=4)
            pygame.draw.rect(surf, WHITE, (bx, by, bw, bh), width=1, border_radius=4)

    def make_scanline_overlay(self):
        overlay = pygame.Surface((LOGICAL_W, LOGICAL_H), pygame.SRCALPHA)
        for y in range(0, LOGICAL_H, 3):
            pygame.draw.line(overlay, (0, 0, 0, 26), (0, y), (LOGICAL_W, y))
        return overlay

    def draw_scanlines(self, surf):
        if not self.scanlines:
            return
        surf.blit(self.scanline_overlay, (0, 0))

    def draw_playing(self, surf):
        self.draw_background(surf)
        for pa in self.particles:
            a = clamp(int(255 * (pa.life / pa.maxlife)), 0, 255)
            col = (*pa.color, a)
            s = pygame.Surface((int(pa.size * 2), int(pa.size * 2)), pygame.SRCALPHA)
            pygame.draw.circle(s, col, (int(pa.size), int(pa.size)), int(pa.size))
            surf.blit(s, (pa.x - pa.size, pa.y - pa.size), special_flags=pygame.BLEND_RGBA_ADD)
        for b in self.bolts:
            self.draw_bolt(surf, b)
        for e in self.enemies:
            self.draw_enemy(surf, e)
        for p in self.players:
            self.draw_ship(surf, p)
        for bl in self.blasts:
            frame_idx = min(len(bl.frames) - 1, int((bl.t / bl.dur) * len(bl.frames)))
            spr = bl.frames[frame_idx]
            if bl.scale != 1.0:
                spr = pygame.transform.smoothscale(spr, (int(spr.get_width() * bl.scale), int(spr.get_height() * bl.scale)))
            rect = spr.get_rect(center=(int(bl.x), int(bl.y)))
            surf.blit(spr, rect, special_flags=pygame.BLEND_RGBA_ADD)
        self.draw_hud(surf)
        self.draw_scanlines(surf)
        if self.paused:
            self.draw_pause_overlay(surf)

    def draw_pause_overlay(self, surf):
        overlay = pygame.Surface((LOGICAL_W, LOGICAL_H), pygame.SRCALPHA)
        overlay.fill((5, 6, 14, 170))
        surf.blit(overlay, (0, 0))
        title = self.font_big.render(self.t("paused"), True, NEON_CYAN_SOFT)
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, LOGICAL_H // 2 - 20)))
        hint = self.font_small.render(self.t("paused_hint"), True, GRAY)
        surf.blit(hint, hint.get_rect(center=(LOGICAL_W // 2, LOGICAL_H // 2 + 30)))

    def draw_menu_frame(self, surf, title_key):
        self.draw_background(surf)
        title = self.font_title.render(self.t("title"), True, WHITE)
        glow = self.font_title.render(self.t("title"), True, NEON_CYAN)
        glow.set_alpha(120)
        for ox, oy in ((-2, 0), (2, 0), (0, -2), (0, 2)):
            surf.blit(glow, glow.get_rect(center=(LOGICAL_W // 2 + ox, 110 + oy)))
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, 110)))
        self.draw_scanlines(surf)

    def draw_menu(self, surf):
        self.draw_menu_frame(surf, "title")
        best_s = self.font_small.render(self.t("best_score", self.data["highscore"]), True, GRAY)
        surf.blit(best_s, best_s.get_rect(center=(LOGICAL_W // 2, 172)))
        ver_s = self.font_tiny.render("v" + GAME_VERSION, True, DARK_GRAY)
        surf.blit(ver_s, (LOGICAL_W - ver_s.get_width() - 10, LOGICAL_H - 18))
        coins_s = self.font_small.render(self.t("coins_label", self.data["coins"]), True, NEON_YELLOW)
        surf.blit(coins_s, coins_s.get_rect(center=(LOGICAL_W // 2, 198)))

        compact = len(self.menu_keys) > 6
        start_y = 238 if compact else 260
        gap = 42 if compact else 54
        item_font = self.font_med if compact else self.font_big
        self.menu_button_rects = []
        for i, key in enumerate(self.menu_keys):
            label = self.tr("menu_" + key) if key in ("stats", "info", "netset") else self.t("menu_" + key)
            selected = i == self.menu_index
            color = NEON_CYAN_SOFT if selected else WHITE
            txt = item_font.render(label, True, color)
            rect = txt.get_rect(center=(LOGICAL_W // 2, start_y + i * gap))
            if selected:
                pad_rect = rect.inflate(50, 18)
                pygame.draw.rect(surf, (*NEON_CYAN, 40), pad_rect, border_radius=10)
                pygame.draw.rect(surf, NEON_CYAN, pad_rect, width=2, border_radius=10)
            surf.blit(txt, rect)
            self.menu_button_rects.append((rect.inflate(50, 18), key))

        hint = self.font_tiny.render(self.t("menu_hint"), True, GRAY)
        surf.blit(hint, hint.get_rect(center=(LOGICAL_W // 2, LOGICAL_H - 24)))

    def draw_settings(self, surf):
        self.draw_menu_frame(surf, "settings_title")
        title = self.font_big.render(self.t("settings_title"), True, NEON_CYAN_SOFT)
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, 200)))

        rows = [
            (self.t("language_label"), TEXTS[self.lang]["lang_names"][self.lang]),
            (self.t("graphics_label"), TEXTS[self.lang]["quality_names"][self.quality]),
            (self.t("back_label"), ""),
        ]
        start_y = 280
        gap = 60
        for i, (label, value) in enumerate(rows):
            selected = i == self.settings_index
            color = NEON_CYAN_SOFT if selected else WHITE
            line = f"{label}" + (f"   ◄ {value} ►" if value else "")
            txt = self.font_med.render(line, True, color)
            rect = txt.get_rect(center=(LOGICAL_W // 2, start_y + i * gap))
            if selected:
                pygame.draw.rect(surf, (*NEON_CYAN, 35), rect.inflate(40, 14), border_radius=8)
            surf.blit(txt, rect)

        hint = self.font_tiny.render(self.t("settings_hint"), True, GRAY)
        surf.blit(hint, hint.get_rect(center=(LOGICAL_W // 2, LOGICAL_H - 24)))

    def draw_shop(self, surf):
        self.draw_menu_frame(surf, "shop_title")
        title = self.font_big.render(self.t("shop_title"), True, NEON_YELLOW)
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, 175)))
        coins_s = self.font_small.render(self.t("coins_label", self.data["coins"]), True, NEON_YELLOW)
        surf.blit(coins_s, coins_s.get_rect(center=(LOGICAL_W // 2, 210)))

        start_y = 270
        gap = 70
        for i, item in enumerate(SHOP_ITEMS):
            lvl = self.data["upgrades"].get(item["id"], 0)
            maxed = lvl >= item["max"]
            cost = shop_item_cost(item, lvl)
            selected = i == self.shop_index
            label = self.t(item["label_key"])
            lvl_s = self.t("shop_level", lvl, item["max"])
            cost_s = self.t("shop_maxed") if maxed else self.t("shop_buy", cost)
            color = NEON_CYAN_SOFT if selected else WHITE
            cost_color = GRAY if maxed else (NEON_GREEN if self.data["coins"] >= cost else NEON_RED_SOFT)

            y = start_y + i * gap
            if selected:
                pygame.draw.rect(surf, (*NEON_CYAN, 30), pygame.Rect(LOGICAL_W // 2 - 300, y - 24, 600, 54), border_radius=8)
            name_txt = self.font_med.render(label, True, color)
            surf.blit(name_txt, (LOGICAL_W // 2 - 290, y - 20))
            lvl_txt = self.font_small.render(lvl_s, True, GRAY)
            surf.blit(lvl_txt, (LOGICAL_W // 2 - 290, y + 8))
            cost_txt = self.font_med.render(cost_s, True, cost_color)
            surf.blit(cost_txt, cost_txt.get_rect(midright=(LOGICAL_W // 2 + 290, y)))
            # индикатор уровня
            bar_x = LOGICAL_W // 2 + 40
            for seg in range(item["max"]):
                col = NEON_CYAN if seg < lvl else DARK_GRAY
                pygame.draw.rect(surf, col, (bar_x + seg * 16, y + 4, 10, 10), border_radius=2)

        hint = self.font_tiny.render(self.t("shop_hint"), True, GRAY)
        surf.blit(hint, hint.get_rect(center=(LOGICAL_W // 2, LOGICAL_H - 24)))

    def draw_coop_info(self, surf):
        self.draw_menu_frame(surf, "coop_lobby_title")
        title = self.font_big.render(self.t("coop_lobby_title"), True, NEON_CYAN_SOFT)
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, LOGICAL_H // 2 - 130)))
        y = LOGICAL_H // 2 - 60
        for key, color in ((("coop_p1"), PLAYER1_COLOR), (("coop_p2"), PLAYER2_COLOR)):
            txt = self.font_med.render(self.t(key), True, color)
            surf.blit(txt, txt.get_rect(center=(LOGICAL_W // 2, y)))
            y += 50
        hint = self.font_small.render(self.t("coop_start"), True, GRAY)
        surf.blit(hint, hint.get_rect(center=(LOGICAL_W // 2, y + 40)))

    def draw_gameover(self, surf):
        self.draw_menu_frame(surf, "game_over")
        title = self.font_big.render(self.t("game_over"), True, NEON_RED_SOFT)
        surf.blit(title, title.get_rect(center=(LOGICAL_W // 2, 220)))
        score_txt = self.font_med.render(self.t("your_score", self.score), True, WHITE)
        surf.blit(score_txt, score_txt.get_rect(center=(LOGICAL_W // 2, 280)))
        if self.score >= self.data["highscore"] and self.score > 0:
            rec = self.font_med.render(self.t("new_record"), True, NEON_YELLOW)
            surf.blit(rec, rec.get_rect(center=(LOGICAL_W // 2, 320)))
