    def handle_settings_input(self, event):
        if event.type != pygame.KEYDOWN:
            return
        if event.key in (pygame.K_UP, pygame.K_w):
            self.settings_index = (self.settings_index - 1) % 3
            self.play_sound("select")
        elif event.key in (pygame.K_DOWN, pygame.K_s):
            self.settings_index = (self.settings_index + 1) % 3
            self.play_sound("select")
        elif event.key == pygame.K_ESCAPE:
            self.save()
            self.state = "menu"
        elif event.key in (pygame.K_LEFT, pygame.K_RIGHT, pygame.K_a, pygame.K_d, pygame.K_RETURN):
            if self.settings_index == 0:
                idx = LANGUAGES.index(self.lang)
                idx = (idx + 1) % len(LANGUAGES)
                self.lang = LANGUAGES[idx]
                self.play_sound("select")
            elif self.settings_index == 1:
                idx = QUALITY_LEVELS.index(self.quality)
                delta = 1 if event.key in (pygame.K_RIGHT, pygame.K_d, pygame.K_RETURN) else -1
                idx = (idx + delta) % len(QUALITY_LEVELS)
                self.quality = QUALITY_LEVELS[idx]
                self.rebuild_quality_assets()
                self.scanlines = QUALITY_SETTINGS[self.quality]["scanlines"]
                self.play_sound("select")
            elif self.settings_index == 2 and event.key == pygame.K_RETURN:
                self.save()
                self.state = "menu"

    def handle_shop_input(self, event):
        if event.type != pygame.KEYDOWN:
            return
        n = len(SHOP_ITEMS)
        if event.key in (pygame.K_UP, pygame.K_w):
            self.shop_index = (self.shop_index - 1) % n
            self.play_sound("select")
        elif event.key in (pygame.K_DOWN, pygame.K_s):
            self.shop_index = (self.shop_index + 1) % n
            self.play_sound("select")
        elif event.key == pygame.K_ESCAPE:
            self.state = "menu"
        elif event.key in (pygame.K_RETURN, pygame.K_SPACE):
            item = SHOP_ITEMS[self.shop_index]
            lvl = self.data["upgrades"].get(item["id"], 0)
            if lvl < item["max"]:
                cost = shop_item_cost(item, lvl)
                if self.data["coins"] >= cost:
                    self.data["coins"] -= cost
                    self.data["upgrades"][item["id"]] = lvl + 1
                    write_save(self.data)
                    self.play_sound("buy")

