    # ───────── МУЛЬТИПЛЕЕР: создание LAN-игры (HOST) ─────────
    def enter_mp_create(self):
        self.net_cleanup()
        self.mp_error = None
        try:
            port = int(self.mp_port_text) if self.mp_port_text else net.DEFAULT_PORT
        except ValueError:
            port = net.DEFAULT_PORT
        self.net_server = net.LANServer(port=port, max_players=2)
        try:
            self.net_server.start()
            self.net_role = "host"
            self.net_advertiser = net.LobbyAdvertiser(game_port=port, name="Neon Defender", max_players=2)
            self.net_advertiser.get_player_count = lambda: 1 + len(self.mp_lobby_players)
            self.net_advertiser.start()
        except ConnectionError:
            self.net_server = None
            self.mp_error = self.t("mp_port_error")
        self.mp_local_ip = net.get_local_ip()
        self.state = "mp_create"

    def handle_mp_create_input(self, event):
        if event.type != pygame.KEYDOWN:
            return
        if event.key == pygame.K_ESCAPE:
            self.net_cleanup()
            self.state = "mp_menu"
        elif event.key == pygame.K_RETURN:
            if self.net_server and self.net_server.player_count() >= 1:
                if self.net_advertiser:
                    self.net_advertiser.stop()
                    self.net_advertiser = None
                self.net_server.broadcast({"type": "start"})
                self.start_lan_run(is_host=True)

    def update_mp_create(self, dt):
        if not self.net_server:
            return
        for ev in self.net_server.get_events():
            kind = ev[0]
            if kind == "connected":
                _, pid, name = ev
                self.mp_lobby_players[pid] = name
                self.play_sound("confirm")
            elif kind == "disconnected":
                _, pid, _ = ev
                self.mp_lobby_players.pop(pid, None)

