    # ───────── МУЛЬТИПЛЕЕР: лобби — список найденных LAN-игр ─────────
    def enter_mp_browse(self):
        self.net_cleanup()
        self.mp_error = None
        self.mp_browse_index = 0
        self.net_browser = net.LobbyBrowser()
        try:
            self.net_browser.start()
        except Exception:
            self.net_browser = None
        self.state = "mp_browse"

    def handle_mp_browse_input(self, event):
        if event.type != pygame.KEYDOWN:
            return
        games = self.net_browser.list_games() if self.net_browser else []
        n = len(games) + 1  # + пункт "ввести IP вручную"
        if event.key in (pygame.K_UP, pygame.K_w):
            self.mp_browse_index = (self.mp_browse_index - 1) % n
            self.play_sound("select")
        elif event.key in (pygame.K_DOWN, pygame.K_s):
            self.mp_browse_index = (self.mp_browse_index + 1) % n
            self.play_sound("select")
        elif event.key == pygame.K_ESCAPE:
            self.net_cleanup()
            self.state = "mp_menu"
        elif event.key in (pygame.K_RETURN, pygame.K_SPACE):
            self.play_sound("confirm")
            if self.mp_browse_index >= len(games):
                # "ВВЕСТИ IP ВРУЧНУЮ" — запасной вариант (полезно, если
                # обнаружение по UDP-широковещанию не проходит через
                # конкретную настройку Radmin VPN/роутера)
                self.enter_mp_join()
                return
            game = games[self.mp_browse_index]
            self.net_cleanup()
            self.mp_ip_text = game["ip"]
            self.mp_port_text = str(game["port"])
            self.mp_field = "ip"
            self.mp_error = None
            self.mp_connecting = True
            self.mp_connect_thread = threading.Thread(
                target=self._do_connect, args=(game["ip"], game["port"], self.net_my_name()), daemon=True
            )
            self.state = "mp_join"
            self.mp_connect_thread.start()

    def update_mp_browse(self, dt):
        if self.net_browser:
            games = self.net_browser.list_games()
            n = len(games) + 1
            if self.mp_browse_index >= n:
                self.mp_browse_index = n - 1

